import { z } from "zod";
import { issuePrioritySchema } from "./issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";

export const recurrenceCadenceSchema = z.enum(["daily", "weekly"]);

/** True for a real `YYYY-MM-DD` calendar date (rejects e.g. `2026-02-30`). */
export function isCalendarDate(value: string): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
