    await recurringIssueRepo.findRecurringIssueById(
      input.orgId,
      input.recurringIssueId,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringIssueRepo.setRecurringIssuePaused(
    rule.orgId,
    rule.id,
    input.paused,
  );
}

export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringIssueRepo.listRecurringIssues(orgId);
}

/** True when `userId` is a live, active member of the organization. */
export async function isActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && member.status === "active";
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** The calendar date (`YYYY-MM-DD`) it is in `timezone` at `now`. */
export function localDateIn(now: Date, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    calendar: "gregory",
    numberingSystem: "latn",
    era: "short",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);

  const part = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((p) => p.type === type)?.value ?? "";

  let year = Number(part("year"));
  if (part("era").toUpperCase().startsWith("B")) year = 1 - year;
  return formatDay(year, Number(part("month")), Number(part("day")));
}

function formatDay(year: number, month: number, day: number): string {
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

function dayToUtcMs(day: string): number {
  const [year, month, date] = day.split("-").map(Number);
  const value = new Date(Date.UTC(2000, (month ?? 1) - 1, date ?? 1));
  value.setUTCFullYear(year ?? 2000);
  return value.getTime();
}

function utcMsToDay(ms: number): string {
  const value = new Date(ms);
  return formatDay(
    value.getUTCFullYear(),
    value.getUTCMonth() + 1,
    value.getUTCDate(),
  );
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
export function isoWeekday(day: string): number {
  const weekday = new Date(dayToUtcMs(day)).getUTCDay();
  return weekday === 0 ? 7 : weekday;
}

/**
 * The latest occurrence of `rule` that has started by `now`, or `null` when
 * none has. Day D has started once the local time in the rule's zone has
 * reached 00:00 on D, i.e. once the local calendar date is on or after D.
 */
export function latestOccurrence(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  const today = localDateIn(now, rule.timezone);
  let candidate = today;

  if (rule.cadence === "weekly") {
    const weekday = rule.weekday ?? 1;
    const back = (isoWeekday(today) - weekday + 7) % 7;
    candidate = utcMsToDay(dayToUtcMs(today) - back * MS_PER_DAY);
  }

  return dayToUtcMs(candidate) >= dayToUtcMs(rule.startsOn) ? candidate : null;
}
