/**
 * Turns recurring-issue rules into ordinary issues, filed on behalf of each
 * rule's creator through the normal issue-creation path.
 *
 * Must call (do not reimplement): can, createIssue, isArchived
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import {
  isActiveMember,
  latestOccurrence,
} from "@/server/services/recurring-issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

type Outcome = "created" | "skipped";

/**
 * One pass over every non-paused rule. Each rule files at most one issue per
 * run, for its latest started occurrence — missed ones are never back-filled.
 * `processed` counts the issues created.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if ((await fileOccurrence(rule, now)) === "created") {
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.warn("recurring issue not filed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function fileOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<Outcome> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  if (isArchived(project)) return "skipped";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: creator.userId, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringIssueRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    logger.info("recurring issue paused: creator may no longer file it", {
      recurringIssueId: rule.id,
      orgId: rule.orgId,
    });
    return "skipped";
  }

  const assigneeId =
    rule.assigneeId !== null && (await isActiveMember(rule.orgId, rule.assigneeId))
      ? rule.assigneeId
      : null;

  await createIssue(actor, {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringIssueRepo.setLastOccurrence(rule.orgId, rule.id, occurrence);
  return "created";
}
