afterAll(() => cleanup());

describe("recurring", () => {
  it("schema", () => {
    const base = { orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA", projectId: "01HZZZAAAAAAAAAAAAAAAAAAAB", title: "Daily", cadence: "daily", timezone: "Europe/Berlin", startsOn: "2026-03-01" };
    expect(createRecurringIssueSchema.safeParse(base).success).toBe(true);
    expect(createRecurringIssueSchema.safeParse({ ...base, startsOn: "2026-02-30" }).success).toBe(false);
